package ws

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"github.com/itsmaleen/cmux-companion/bridge/internal/claude"
	"github.com/itsmaleen/cmux-companion/bridge/internal/socket"
)

// Replicates handleClaudeTranscript end-to-end against the LIVE cmux socket
// for every surface, printing what session each surface_id resolves to.
func TestScratchE2E(t *testing.T) {
	sockPath := fmt.Sprintf("%s/.local/state/cmux/cmux-%d.sock", os.Getenv("HOME"), os.Getuid())
	c := socket.NewClient(sockPath, "\x1b") // password is ESC
	if err := c.Connect(); err != nil {
		t.Fatalf("connect: %v", err)
	}
	defer c.Close()

	resolver := claude.NewResolver()

	listRaw, err := c.Send("surface.list", map[string]any{})
	if err != nil {
		t.Fatalf("surface.list: %v", err)
	}
	var lp struct {
		Surfaces []map[string]any `json:"surfaces"`
	}
	if err := json.Unmarshal(listRaw, &lp); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}

	for _, s := range lp.Surfaces {
		id, _ := s["id"].(string)
		title, _ := s["title"].(string)
		rb, _ := s["resume_binding"].(map[string]any)
		kind, _ := rb["kind"].(string)
		if kind != "claude" {
			continue
		}
		cp, _ := rb["checkpoint_id"].(string)
		text, supported, sid, err := resolver.Render(rb, 300)
		head := text
		if len(head) > 60 {
			head = head[:60]
		}
		fmt.Printf("\nsurface=%s\n  title=%q\n  checkpoint=%s\n  -> resolved_sid=%s supported=%v err=%v\n  head=%q\n",
			id, title, cp, sid, supported, err, head)
	}
}
EOF
